import csv
import logging
import os

from taf.config.testline.info.exceptions import (RUNotSupported, SWLineNotSupported, UserNotDefinedForSWLine,
                                                 FHInterfaceNotSupported)

logger = logging.getLogger(__name__)


class RuListAttrs(object):

    def __init__(self,
                 ru_list_csv_path=os.path.join(os.path.dirname(__file__), 'data/ru_list.csv'),
                 ru_list_rejected_csv_path=os.path.join(os.path.dirname(__file__), 'data/ru_list_rejected.csv'),
                 ru_credentials_csv_path=os.path.join(os.path.dirname(__file__), 'data/ru_credentials.csv')):
        self.ru_data = self._parse_csv_file(ru_list_csv_path)
        self.ru_rejected_data = self._parse_csv_file(ru_list_rejected_csv_path)
        self.ru_credentials_data = self._parse_csv_file(ru_credentials_csv_path)
        self.all_ru_data = self.ru_data + self.ru_rejected_data
        self._all_radio_sw_lines = {ru_detail['RFSW Line'] for ru_detail in self.ru_data if ru_detail['RFSW Line']}

    def get_ru_duplex_method(self, radio_type, fh_interface=None):
        return self._get_ru_attribute(ru_data=self.all_ru_data,
                                      radio_type=radio_type, fh_interface=fh_interface, attribute_name='Duplex')

    def get_ru_sw_line(self, radio_type, fh_interface=None):
        return self._get_ru_attribute(ru_data=self.all_ru_data,
                                      radio_type=radio_type, fh_interface=fh_interface, attribute_name='RFSW Line')

    def get_ru_password(self, radio_sw_line=None, radio_type=None, username='serviceuser', fh_interface=None):
        """
        Gets password for given SW Line/radio_type and user from ru_credentials.csv file. One of the parameters
        'radio_sw_line' or 'radio_type' must be provided.
        :param radio_sw_line: SW Line of radio
        :param radio_type: type of radio
        :param username: user for which password is returned
        :param fh_interface: FH interface of radio eg CPRI,eCPRI
        :return: password for given SW Line and user
        """
        if radio_sw_line is not None:
            return self._get_ru_password_based_on_rfsw_line(radio_sw_line, username)
        elif radio_type is not None:
            return self._get_ru_password_based_on_radio_type(radio_type, username, fh_interface)
        else:
            raise ValueError("One of the parameters 'radio_sw_line' or 'radio_type' must be provided.")

    def _get_ru_password_based_on_rfsw_line(self, radio_sw_line, username):
        for ru_detail in self.ru_credentials_data:
            if ru_detail['RFSW Line'] == radio_sw_line and ru_detail['Username'] == username:
                return ru_detail['Password']
        if radio_sw_line in self._all_radio_sw_lines:
            raise UserNotDefinedForSWLine(f'User {username} not defined for SW Line {radio_sw_line}')
        raise SWLineNotSupported(f'No support for SW Line {radio_sw_line} and user {username}')

    def _get_ru_password_based_on_radio_type(self, radio_type, username, fh_interface):
        rfsw_line = self._get_ru_attribute(ru_data=self.ru_data, radio_type=radio_type,
                                           fh_interface=fh_interface, attribute_name='RFSW Line')
        return self._get_ru_password_based_on_rfsw_line(rfsw_line, username)

    def _get_ru_attribute(self, ru_data, radio_type, fh_interface, attribute_name):
        matching_rus = [
            ru_detail for ru_detail in ru_data
            if ru_detail['RU name'] == radio_type
        ]

        if not matching_rus:
            raise RUNotSupported(f"No support for RU {radio_type}")

        # If multiple entries exist, handle FH interface filtering
        if len(matching_rus) > 1:
            if fh_interface is None:
                logger.warning(
                    f"RU {radio_type} has multiple entries. Please provide a specific FH interface."
                    f"Returning the first entry's {attribute_name}."
                )
            else:
                for ru_detail in matching_rus:
                    if ru_detail['FH interface'] == fh_interface:
                        return ru_detail[attribute_name]
                raise FHInterfaceNotSupported(f"No matching FH interface {fh_interface} found for {radio_type} RU.")

        return matching_rus[0][attribute_name]

    @staticmethod
    def _parse_csv_file(csv_file_path):
        with open(csv_file_path) as csv_file:
            csv_reader = csv.DictReader(csv_file, delimiter=';')
            return list(csv_reader)
